- **Is there an existing error class or HTTP wrapper?** If the project already has, say, a `ApiError` or an `httpClient` that sets the base URL and auth headers, I should use those instead of importing `fetch` directly — I assumed none exist.
- **What's the real shape of an order?** My `isOrder` guard is a placeholder; if there's a zod schema or a generated API type, use that and delete the guard.
- **Is 5s right?** The budget should match the p99 of the real API plus headroom; I picked a default, not a measured value.

# Implementing `fetchOrder`

No project files were provided, so I'll implement against the conventions this skill enforces and flag the one assumption I'm making (module system + error shape). If you paste your `package.json`/`tsconfig.json` I'll reconcile it exactly.

**Assumption:** ESM TypeScript project (`"type": "module"`, `tsconfig` `moduleResolution: "nodenext"`). If you're on CommonJS, the only change is dropping the `node:`-prefixed built-ins (there are none here anyway — this only uses `fetch`, a global).

## The function

```ts
// src/orders/fetchOrder.ts

export class OrderNotFoundError extends Error {
  constructor(readonly orderId: string) {
    super(`Order not found: ${orderId}`);
    this.name = "OrderNotFoundError";
  }
}

export class OrdersApiError extends Error {
  constructor(
    message: string,
    readonly status: number,
    options?: { cause?: unknown },
  ) {
    super(message, options);
    this.name = "OrdersApiError";
  }
}

const ORDERS_API_BASE_URL = process.env.ORDERS_API_BASE_URL;
if (!ORDERS_API_BASE_URL) {
  throw new Error("Missing required env var ORDERS_API_BASE_URL");
}

const DEFAULT_TIMEOUT_MS = 5_000;

export interface Order {
  id: string;
  status: "pending" | "paid" | "shipped" | "cancelled";
  totalCents: number;
}

export async function fetchOrder(
  id: string,
  { signal, timeoutMs = DEFAULT_TIMEOUT_MS }: { signal?: AbortSignal; timeoutMs?: number } = {},
): Promise<Order> {
  if (typeof id !== "string" || id.trim() === "") {
    throw new TypeError("fetchOrder: id must be a non-empty string");
  }

  // Combine the caller's cancellation with an independent timeout budget so
  // the call can't hang forever even if the caller passes no signal.
  const timeoutSignal = AbortSignal.timeout(timeoutMs);
  const combinedSignal = signal
    ? AbortSignal.any([signal, timeoutSignal])
    : timeoutSignal;

  let response: Response;
  try {
    response = await fetch(
      `${ORDERS_API_BASE_URL}/orders/${encodeURIComponent(id)}`,
      { signal: combinedSignal, headers: { accept: "application/json" } },
    );
  } catch (err) {
    if (combinedSignal.aborted) {
      throw new OrdersApiError(
        timeoutSignal.aborted
          ? `Orders API timed out after ${timeoutMs}ms fetching order ${id}`
          : `Fetching order ${id} was cancelled`,
        0,
        { cause: err },
      );
    }
    throw new OrdersApiError(
      `Orders API request failed for order ${id}`,
      0,
      { cause: err },
    );
  }

  if (response.status === 404) {
    throw new OrderNotFoundError(id);
  }
  if (!response.ok) {
    throw new OrdersApiError(
      `Orders API returned ${response.status} for order ${id}`,
      response.status,
    );
  }

  const body: unknown = await response.json();
  return parseOrder(body, id);
}
```

## The validation helper

`response.json()` returns `any`. Per the boundary rule, the parsed body is
treated as `unknown` and narrowed before it reaches business logic:

```ts
function parseOrder(body: unknown, orderId: string): Order {
  if (typeof body !== "object" || body === null) {
    throw new OrdersApiError(
      `Orders API returned non-object body for order ${orderId}`,
      200,
    );
  }
  const o = body as Record<string, unknown>;
  const validStatus = ["pending", "paid", "shipped", "cancelled"] as const;
  if (
    typeof o.id !== "string" ||
    typeof o.totalCents !== "number" ||
    !validStatus.includes(o.status as (typeof validStatus)[number])
  ) {
    throw new OrdersApiError(
      `Orders API returned malformed order payload for ${orderId}`,
      200,
    );
  }
  return {
    id: o.id,
    status: o.status as Order["status"],
