import { fetch } from "undici"; // NOTE: Node 18+ has global fetch; see the drop-in comment below.

/** How long we're willing to wait for the upstream orders API. */
const REQUEST_TIMEOUT_MS = 5_000;

const ORDERS_API_BASE =
  process.env.ORDERS_API_BASE_URL ?? "http://orders.internal";

/** Reject obviously malformed ids before they hit the network. */
const ORDER_ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;

export interface Order {
  id: string;
  status: string;
  totalCents: number;
  createdAt: string;
}

/**
 * Raised when the orders API cannot be reached or returns an unusable
 * response. Distinct from a 404, which is a valid "order does not exist".
 */
export class OrdersApiError extends Error {
  constructor(message: string, options?: { cause?: unknown }) {
    super(message, options);
    this.name = "OrdersApiError";
  }
}

/** Raised when the order is validly requested but does not exist. */
export class OrderNotFoundError extends Error {
  constructor(readonly id: string) {
    super(`Order not found: ${id}`);
    this.name = "OrderNotFoundError";
  }
}

// Note: `new Error(msg, { cause })` and `AbortSignal.timeout` both require
// Node 18.17+ / a lib target of ES2022+. Adjust if you're on older Node.

export async function fetchOrder(id: string): Promise<Order> {
  // --- Boundary validation: reject before doing any I/O -----------------
  if (typeof id !== "string" || !ORDER_ID_PATTERN.test(id)) {
    // A programming error on the caller's side -> throw, don't hit network.
    throw new TypeError(`Invalid order id: ${JSON.stringify(id)}`);
  }

  // --- Bounded outbound call: this is what prevents "hang forever" ------
  const signal = AbortSignal.timeout(REQUEST_TIMEOUT_MS);
  const url = `${ORDERS_API_BASE}/orders/${encodeURIComponent(id)}`;

  let response: Response;
  try {
    response = await fetch(url, {
      method: "GET",
      headers: { accept: "application/json" },
      signal, // <- the timeout lives here
    });
  } catch (cause) {
    // AbortSignal.timeout rejects with a TimeoutError DOMException.
    if (cause instanceof Error && cause.name === "TimeoutError") {
      throw new OrdersApiError(
        `Orders API timed out after ${REQUEST_TIMEOUT_MS}ms for order ${id}`,
        { cause },
      );
    }
    // Any other network failure.
    throw new OrdersApiError(`Orders API request failed for order ${id}`, {
      cause,
    });
  }

  // --- Distinguish "not found" from real failures -----------------------
  if (response.status === 404) {
    throw new OrderNotFoundError(id);
  }
  if (!response.ok) {
    throw new OrdersApiError(
      `Orders API returned ${response.status} for order ${id}`,
    );
  }

  // --- Validate the response shape before trusting it -------------------
  const body: unknown = await response.json();
  if (!isOrder(body)) {
    throw new OrdersApiError(
      `Orders API returned a malformed payload for order ${id}`,
    );
  }
  return body;
}

/** Runtime type guard: keeps `unknown` from the network out of business logic. */
function isOrder(value: unknown): value is Order {
  if (typeof value !== "object" || value === null) return false;
  const o = value as Record<string, unknown>;
  return (
    typeof o.id === "string" &&
    typeof o.status === "string" &&
    typeof o.totalCents === "number" &&
    typeof o.createdAt === "string"
  );
}
```

